@test(seed1, seed2) {
    let n = 100
    let max = 100000
    let threshold = 0.05
    let random1 = Math:gen_rng(seed1)
    let random2 = Math:gen_rng(seed2)
    var same = 0
    for n {
        if random1(1, max) == random2(1, max) {
            same += 1
        }
    }
    let rate = same / n
    if seed1 == seed2 { rate == 1 }
    else { rate < threshold }
}
let seed1 = `{Util:uuid()}`
let seed2 = `{Date:year()}`
<: [
    test(seed1, seed1)
    test(seed1, seed2)
]

